def count_modest_substrings(s, l, r):
    count = 0
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            num = int(s[i:j])
            if l <= num <= r:
                count += 1
    return count

def find_largest_modest_string(l, r, n):
    for i in range(n):
        for digit in range(1, 10):
            test_str = '0' * (n - i - 1) + str(digit) * (i + 1)
            if count_modest_substrings(test_str, l, r) == (i + 1) * digit:
                return (i + 1) * digit, test_str
    return 0, ""

